#!/usr/bin/env bash
# DOC-001 config-effect evidence regression check.
#
# Asserts that the off/on evidence artifacts generated by
# scripts/docs/config-switch-evidence.sh exist and are referenced from the
# bilingual docs page, and that the route-only feature flag (extensions) has no
# GUI evidence (its off/on menu is byte-identical, so there is no screenshot to
# keep).
#
# This is the "config effect regression test" deliverable of DOC-001: if a code
# or docs change drops the evidence directory, breaks a reference, or silently
# makes one of the four GUI-visible flags no longer GUI-visible, this fails.
#
# Usage: bash scripts/docs/check-config-evidence.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
EVID="$ROOT/docs/public/evidence/config-effects"
DOCS="$ROOT/docs/operations/config-effects.md"
DOCS_ZH="$ROOT/docs/zh/operations/config-effects.md"
PIPELINE="$ROOT/scripts/docs/config-switch-evidence.sh"

# GUI-visible feature flags (each toggles a top-level console menu).
GUI_FLAGS=(ops support analytics dev)
# Route-only flags: toggling changes no menu (all pages hideInMenu), so there
# must be NO evidence dir for them.
ROUTE_ONLY_FLAGS=(extensions)

fail=0
err() { echo "FAIL: $*" >&2; fail=1; }
ok() { echo "ok: $*"; }

[[ -x "$PIPELINE" ]] || err "pipeline script not executable: $PIPELINE"
[[ -f "$DOCS" ]] || err "docs page missing: $DOCS"
[[ -f "$DOCS_ZH" ]] || err "docs zh page missing: $DOCS_ZH"

for flag in "${GUI_FLAGS[@]}"; do
  for art in "$flag-off.png" "$flag-on.png" "$flag-compare.png" "$flag.gif"; do
    [[ -f "$EVID/featureFlags.$flag/$art" ]] || err "missing evidence artifact: featureFlags.$flag/$art"
  done
  # Each artifact must be referenced from the docs pages (both languages).
  for doc in "$DOCS" "$DOCS_ZH"; do
    grep -q "config-effects/featureFlags.$flag/$flag-compare.png" "$doc" ||
      err "$flag-compare.png not referenced in $(basename "$doc")"
  done
  ok "featureFlags.$flag evidence present + referenced"
done

for flag in "${ROUTE_ONLY_FLAGS[@]}"; do
  if [[ -d "$EVID/featureFlags.$flag" ]]; then
    err "route-only flag $flag has an evidence dir (no GUI change expected)"
  else
    ok "featureFlags.$flag route-only (no evidence dir) — boundary held"
  fi
  grep -q "no menu change\|菜单无变化\|route-only\|仅影响路由" "$DOCS" ||
    err "route-only boundary for $flag not documented in en page"
done

if [[ "$fail" = "1" ]]; then
  echo "config-effect evidence check FAILED" >&2
  exit 1
fi
echo "config-effect evidence check PASSED"
